args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?dir ?dirLabel ?deathDate WHERE {
  VALUES ?film { dbr:Deuce_High dbr:The_King_is_the_Best_Mayor }
  ?film dbo:director ?dir .
  OPTIONAL { ?dir dbo:deathDate ?dd. }
  OPTIONAL { ?dir dbo:deathYear ?dy. }
  OPTIONAL { ?dir dbp:deathDate ?md. }
  BIND(
    COALESCE(
      ?dd,
      xsd:date(CONCAT(STR(?dy), "-", SUBSTR(STR(?md),3)))
    ) AS ?deathDate
  )
  OPTIONAL { ?film rdfs:label ?filmLabel. FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?dir rdfs:label ?dirLabel. FILTER(lang(?dirLabel) = "en") }
}
ORDER BY ?deathDate
LIMIT 1

